/* The 12px rung is a closed list. See lucide-map.mjs for why, and QDS_LINT's
   iconScale check for the guard. */
window.QICONS_XS = ["arrow_down","arrow_up","chevron_down","chevron_left","chevron_right","chevron_up","close"];

/* Builds the <svg> for a glyph. Unchanged contract: name + optional class list,
   where the fill class swaps in the solid cut. One viewBox now — the -2 -2 24 24 padding
   trick is gone, because 24 is the master rather than a box around 20px of art. */
window.QIC = function (name, cls) {
  cls = cls || '';
  var n = name;
  if (/\bfill\b/.test(cls) && window.QICONS[name + '_solid']) n = name + '_solid';
  var d = window.QICONS[n] || window.QICONS[name];
  var c = ('ms ' + cls).trim();
  if (!d) return '<svg class="' + c + '" viewBox="0 0 24 24" aria-hidden="true" focusable="false" data-missing="' + name + '">' +
    '<rect x="2" y="2" width="20" height="20" rx="2" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="2 2" opacity=".5"/></svg>';
  return '<svg class="' + c + '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' + d + '</svg>';
};
